// Generated by scripts/generate-articles.ts. Do not edit.
export default {"html":"<aside class=\"msg alert\"><span class=\"msg-symbol\">!</span><div class=\"msg-content\"><p data-line=\"1\" class=\"code-line\">This article was drafted with AI based on a presentation by Alex from the Angular team, then edited by hand. Some features described are experimental—evaluate carefully before production use.</p>\n</div></aside>\n<p data-line=\"4\" class=\"code-line\">Angular v20 is out! This release adds many features that push signals further. Since signals arrived in Angular 16, developer experience keeps improving.</p>\n<p data-line=\"6\" class=\"code-line\">This article walks through major Angular v20 additions with practical examples.</p>\n<h2 id=\"1.-resource-api%3A-simpler-async\" data-line=\"8\" class=\"code-line\"><a class=\"header-anchor-link\" href=\"#1.-resource-api%3A-simpler-async\" aria-hidden=\"true\"></a> 1. Resource API: simpler async</h2>\n<p data-line=\"10\" class=\"code-line\">Signals excel at reactive, synchronous work—but what about async tasks with unpredictable completion? The new Resource API addresses that.</p>\n<p data-line=\"12\" class=\"code-line\">The Resource API is a primitive for declaring async dependencies as part of the signal graph. A resource exposes status, value, and other properties as signals, so they integrate cleanly with other signal-based logic and templates.</p>\n<h3 id=\"basic-usage\" data-line=\"14\" class=\"code-line\"><a class=\"header-anchor-link\" href=\"#basic-usage\" aria-hidden=\"true\"></a> Basic usage</h3>\n<div class=\"code-block-container\"><pre class=\"shiki github-dark\" style=\"background-color:#151e2c;color:#e1e4e8\"><code class=\"code-line\" data-line=\"16\"><span class=\"line\"><span style=\"color:#E1E4E8\">@</span><span style=\"color:#B392F0\">Component</span><span style=\"color:#E1E4E8\">({</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">  selector: </span><span style=\"color:#9ECBFF\">'app-user-profile'</span><span style=\"color:#E1E4E8\">,</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">  template: </span><span style=\"color:#9ECBFF\">`</span></span>\n<span class=\"line\"><span style=\"color:#9ECBFF\">    @if (userResource.isLoading()) {</span></span>\n<span class=\"line\"><span style=\"color:#9ECBFF\">      &lt;div&gt;Loading...&lt;/div&gt;</span></span>\n<span class=\"line\"><span style=\"color:#9ECBFF\">    } @else if (userResource.error()) {</span></span>\n<span class=\"line\"><span style=\"color:#9ECBFF\">      &lt;div&gt;An error occurred&lt;/div&gt;</span></span>\n<span class=\"line\"><span style=\"color:#9ECBFF\">    } @else if (userResource.hasValue()) {</span></span>\n<span class=\"line\"><span style=\"color:#9ECBFF\">      &lt;div&gt;</span></span>\n<span class=\"line\"><span style=\"color:#9ECBFF\">        &lt;h2&gt;{{ userResource.value().name }}&lt;/h2&gt;</span></span>\n<span class=\"line\"><span style=\"color:#9ECBFF\">        &lt;p&gt;{{ userResource.value().email }}&lt;/p&gt;</span></span>\n<span class=\"line\"><span style=\"color:#9ECBFF\">      &lt;/div&gt;</span></span>\n<span class=\"line\"><span style=\"color:#9ECBFF\">    }</span></span>\n<span class=\"line\"><span style=\"color:#9ECBFF\">  `</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">})</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">export</span><span style=\"color:#F97583\"> class</span><span style=\"color:#B392F0\"> UserProfileComponent</span><span style=\"color:#E1E4E8\"> {</span></span>\n<span class=\"line\"><span style=\"color:#FFAB70\">  userResource</span><span style=\"color:#F97583\"> =</span><span style=\"color:#B392F0\"> resource</span><span style=\"color:#E1E4E8\">(() </span><span style=\"color:#F97583\">=&gt;</span><span style=\"color:#79B8FF\"> this</span><span style=\"color:#E1E4E8\">.</span><span style=\"color:#B392F0\">fetchUserData</span><span style=\"color:#E1E4E8\">());</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">  </span></span>\n<span class=\"line\"><span style=\"color:#F97583\">  private</span><span style=\"color:#B392F0\"> fetchUserData</span><span style=\"color:#E1E4E8\">() {</span></span>\n<span class=\"line\"><span style=\"color:#a0aab5\">    // Fetch data asynchronously</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">    return</span><span style=\"color:#79B8FF\"> this</span><span style=\"color:#E1E4E8\">.http.</span><span style=\"color:#B392F0\">get</span><span style=\"color:#E1E4E8\">&lt;</span><span style=\"color:#B392F0\">User</span><span style=\"color:#E1E4E8\">&gt;(</span><span style=\"color:#9ECBFF\">'/api/user'</span><span style=\"color:#E1E4E8\">);</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">  }</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">}</span></span>\n<span class=\"line\"></span></code></pre></div><h3 id=\"resource-state\" data-line=\"42\" class=\"code-line\"><a class=\"header-anchor-link\" href=\"#resource-state\" aria-hidden=\"true\"></a> Resource state</h3>\n<p data-line=\"44\" class=\"code-line\">A resource has these states:</p>\n<ul data-line=\"46\" class=\"code-line\">\n<li data-line=\"46\" class=\"code-line\"><code>isLoading</code>: whether data is being fetched</li>\n<li data-line=\"47\" class=\"code-line\"><code>error</code>: error information when something fails</li>\n<li data-line=\"48\" class=\"code-line\"><code>hasValue</code>: whether a value was obtained</li>\n<li data-line=\"49\" class=\"code-line\"><code>value</code>: the fetched value</li>\n</ul>\n<p data-line=\"51\" class=\"code-line\">All of these are signals, so templates can use them reactively.</p>\n<h2 id=\"2.-http-resource%3A-even-easier-data-fetching\" data-line=\"53\" class=\"code-line\"><a class=\"header-anchor-link\" href=\"#2.-http-resource%3A-even-easier-data-fetching\" aria-hidden=\"true\"></a> 2. HTTP Resource: even easier data fetching</h2>\n<p data-line=\"55\" class=\"code-line\">Built on the Resource API, an experimental HTTP Resource runs HTTP requests reactively for data fetching.</p>\n<h3 id=\"basic-usage-1\" data-line=\"57\" class=\"code-line\"><a class=\"header-anchor-link\" href=\"#basic-usage-1\" aria-hidden=\"true\"></a> Basic usage</h3>\n<div class=\"code-block-container\"><pre class=\"shiki github-dark\" style=\"background-color:#151e2c;color:#e1e4e8\"><code class=\"code-line\" data-line=\"59\"><span class=\"line\"><span style=\"color:#E1E4E8\">@</span><span style=\"color:#B392F0\">Component</span><span style=\"color:#E1E4E8\">({</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">  selector: </span><span style=\"color:#9ECBFF\">'app-data-display'</span><span style=\"color:#E1E4E8\">,</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">  template: </span><span style=\"color:#9ECBFF\">`</span></span>\n<span class=\"line\"><span style=\"color:#9ECBFF\">    @if (dataResource.isLoading()) {</span></span>\n<span class=\"line\"><span style=\"color:#9ECBFF\">      &lt;div&gt;Loading data...&lt;/div&gt;</span></span>\n<span class=\"line\"><span style=\"color:#9ECBFF\">    } @else if (dataResource.error()) {</span></span>\n<span class=\"line\"><span style=\"color:#9ECBFF\">      &lt;div&gt;Error: {{ dataResource.error().message }}&lt;/div&gt;</span></span>\n<span class=\"line\"><span style=\"color:#9ECBFF\">    } @else if (dataResource.hasValue()) {</span></span>\n<span class=\"line\"><span style=\"color:#9ECBFF\">      &lt;div&gt;</span></span>\n<span class=\"line\"><span style=\"color:#9ECBFF\">        {{ dataResource.value() | json }}</span></span>\n<span class=\"line\"><span style=\"color:#9ECBFF\">      &lt;/div&gt;</span></span>\n<span class=\"line\"><span style=\"color:#9ECBFF\">    }</span></span>\n<span class=\"line\"><span style=\"color:#9ECBFF\">  `</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">})</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">export</span><span style=\"color:#F97583\"> class</span><span style=\"color:#B392F0\"> DataDisplayComponent</span><span style=\"color:#E1E4E8\"> {</span></span>\n<span class=\"line\"><span style=\"color:#FFAB70\">  dataResource</span><span style=\"color:#F97583\"> =</span><span style=\"color:#B392F0\"> httpResource</span><span style=\"color:#E1E4E8\">(() </span><span style=\"color:#F97583\">=&gt;</span><span style=\"color:#9ECBFF\"> '/api/data'</span><span style=\"color:#E1E4E8\">);</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">}</span></span>\n<span class=\"line\"></span></code></pre></div><h2 id=\"3.-streaming-from-resources\" data-line=\"79\" class=\"code-line\"><a class=\"header-anchor-link\" href=\"#3.-streaming-from-resources\" aria-hidden=\"true\"></a> 3. Streaming from resources</h2>\n<p data-line=\"81\" class=\"code-line\">The resource primitive now supports streaming values—handy when you need to stream responses to the client.</p>\n<h3 id=\"streaming-example\" data-line=\"83\" class=\"code-line\"><a class=\"header-anchor-link\" href=\"#streaming-example\" aria-hidden=\"true\"></a> Streaming example</h3>\n<div class=\"code-block-container\"><pre class=\"shiki github-dark\" style=\"background-color:#151e2c;color:#e1e4e8\"><code class=\"code-line\" data-line=\"85\"><span class=\"line\"><span style=\"color:#E1E4E8\">@</span><span style=\"color:#B392F0\">Component</span><span style=\"color:#E1E4E8\">({</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">  template: </span><span style=\"color:#9ECBFF\">`{{ dataStream.value() }}`</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">})</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">export</span><span style=\"color:#F97583\"> class</span><span style=\"color:#B392F0\"> App</span><span style=\"color:#E1E4E8\"> {</span></span>\n<span class=\"line\"><span style=\"color:#a0aab5\">  // Put the WebSocket initialization logic here...</span></span>\n<span class=\"line\"><span style=\"color:#a0aab5\">  // ...</span></span>\n<span class=\"line\"><span style=\"color:#a0aab5\">  // Initialize the streaming resource</span></span>\n<span class=\"line\"><span style=\"color:#FFAB70\">  dataStream</span><span style=\"color:#F97583\"> =</span><span style=\"color:#B392F0\"> resource</span><span style=\"color:#E1E4E8\">({</span></span>\n<span class=\"line\"><span style=\"color:#B392F0\">    stream</span><span style=\"color:#E1E4E8\">: () </span><span style=\"color:#F97583\">=&gt;</span><span style=\"color:#E1E4E8\"> {</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">      return</span><span style=\"color:#F97583\"> new</span><span style=\"color:#79B8FF\"> Promise</span><span style=\"color:#E1E4E8\">&lt;</span><span style=\"color:#B392F0\">Signal</span><span style=\"color:#E1E4E8\">&lt;</span><span style=\"color:#B392F0\">ResourceStreamItem</span><span style=\"color:#E1E4E8\">&lt;</span><span style=\"color:#79B8FF\">string</span><span style=\"color:#E1E4E8\">[]&gt;&gt;&gt;((</span><span style=\"color:#FFAB70\">resolve</span><span style=\"color:#E1E4E8\">) </span><span style=\"color:#F97583\">=&gt;</span><span style=\"color:#E1E4E8\"> {</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">        const</span><span style=\"color:#79B8FF\"> resourceResult</span><span style=\"color:#F97583\"> =</span><span style=\"color:#B392F0\"> signal</span><span style=\"color:#E1E4E8\">&lt;{ </span><span style=\"color:#FFAB70\">value</span><span style=\"color:#F97583\">:</span><span style=\"color:#79B8FF\"> string</span><span style=\"color:#E1E4E8\">[] }&gt;({</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">          value: [],</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">        });</span></span>\n<span class=\"line\"></span>\n<span class=\"line\"><span style=\"color:#79B8FF\">        this</span><span style=\"color:#E1E4E8\">.socket.</span><span style=\"color:#B392F0\">onmessage</span><span style=\"color:#F97583\"> =</span><span style=\"color:#FFAB70\"> event</span><span style=\"color:#F97583\"> =&gt;</span><span style=\"color:#E1E4E8\"> {</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">          resourceResult.</span><span style=\"color:#B392F0\">update</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#FFAB70\">current</span><span style=\"color:#F97583\"> =&gt;</span><span style=\"color:#E1E4E8\"> ({</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">             value: [</span><span style=\"color:#F97583\">...</span><span style=\"color:#E1E4E8\">current.value, event.data]</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">          });</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">        };</span></span>\n<span class=\"line\"></span>\n<span class=\"line\"><span style=\"color:#B392F0\">        resolve</span><span style=\"color:#E1E4E8\">(resourceResult);</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">      });</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">    },</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">  });</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">}</span></span>\n<span class=\"line\"></span></code></pre></div><h2 id=\"4.-signal-api-family-stabilized\" data-line=\"113\" class=\"code-line\"><a class=\"header-anchor-link\" href=\"#4.-signal-api-family-stabilized\" aria-hidden=\"true\"></a> 4. Signal API family stabilized</h2>\n<p data-line=\"115\" class=\"code-line\"><code>linkedSignal</code>, <code>effect</code>, <code>afterNextRender</code>, and <code>afterEveryRender</code> graduated to stable and are production-ready.</p>\n<h3 id=\"practical-example\" data-line=\"117\" class=\"code-line\"><a class=\"header-anchor-link\" href=\"#practical-example\" aria-hidden=\"true\"></a> Practical example</h3>\n<div class=\"code-block-container\"><pre class=\"shiki github-dark\" style=\"background-color:#151e2c;color:#e1e4e8\"><code class=\"code-line\" data-line=\"119\"><span class=\"line\"><span style=\"color:#E1E4E8\">@</span><span style=\"color:#B392F0\">Component</span><span style=\"color:#E1E4E8\">({</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">  selector: </span><span style=\"color:#9ECBFF\">'app-example'</span><span style=\"color:#E1E4E8\">,</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">  template: </span><span style=\"color:#9ECBFF\">`</span></span>\n<span class=\"line\"><span style=\"color:#9ECBFF\">    &lt;div&gt;{{ count() }}&lt;/div&gt;</span></span>\n<span class=\"line\"><span style=\"color:#9ECBFF\">    &lt;button (click)=\"increment()\"&gt;Increment&lt;/button&gt;</span></span>\n<span class=\"line\"><span style=\"color:#9ECBFF\">  `</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">})</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">export</span><span style=\"color:#F97583\"> class</span><span style=\"color:#B392F0\"> ExampleComponent</span><span style=\"color:#E1E4E8\"> {</span></span>\n<span class=\"line\"><span style=\"color:#FFAB70\">  count</span><span style=\"color:#F97583\"> =</span><span style=\"color:#B392F0\"> signal</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#79B8FF\">0</span><span style=\"color:#E1E4E8\">);</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">  </span></span>\n<span class=\"line\"><span style=\"color:#F97583\">  constructor</span><span style=\"color:#E1E4E8\">() {</span></span>\n<span class=\"line\"><span style=\"color:#a0aab5\">    // Watch for value changes</span></span>\n<span class=\"line\"><span style=\"color:#B392F0\">    effect</span><span style=\"color:#E1E4E8\">(() </span><span style=\"color:#F97583\">=&gt;</span><span style=\"color:#E1E4E8\"> {</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">      console.</span><span style=\"color:#B392F0\">log</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#9ECBFF\">'Count changed:'</span><span style=\"color:#E1E4E8\">, </span><span style=\"color:#79B8FF\">this</span><span style=\"color:#E1E4E8\">.</span><span style=\"color:#B392F0\">count</span><span style=\"color:#E1E4E8\">());</span></span>\n<span class=\"line\"><span style=\"color:#79B8FF\">      this</span><span style=\"color:#E1E4E8\">.</span><span style=\"color:#B392F0\">updateAnalytics</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#79B8FF\">this</span><span style=\"color:#E1E4E8\">.</span><span style=\"color:#B392F0\">count</span><span style=\"color:#E1E4E8\">());</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">    });</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">    </span></span>\n<span class=\"line\"><span style=\"color:#a0aab5\">    // Post-render processing</span></span>\n<span class=\"line\"><span style=\"color:#B392F0\">    afterNextRender</span><span style=\"color:#E1E4E8\">(() </span><span style=\"color:#F97583\">=&gt;</span><span style=\"color:#E1E4E8\"> {</span></span>\n<span class=\"line\"><span style=\"color:#79B8FF\">      this</span><span style=\"color:#E1E4E8\">.</span><span style=\"color:#B392F0\">updateDOM</span><span style=\"color:#E1E4E8\">();</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">    });</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">  }</span></span>\n<span class=\"line\"></span>\n<span class=\"line\"><span style=\"color:#B392F0\">  increment</span><span style=\"color:#E1E4E8\">() {</span></span>\n<span class=\"line\"><span style=\"color:#79B8FF\">    this</span><span style=\"color:#E1E4E8\">.count.</span><span style=\"color:#B392F0\">update</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#FFAB70\">v</span><span style=\"color:#F97583\"> =&gt;</span><span style=\"color:#E1E4E8\"> v </span><span style=\"color:#F97583\">+</span><span style=\"color:#79B8FF\"> 1</span><span style=\"color:#E1E4E8\">);</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">  }</span></span>\n<span class=\"line\"></span>\n<span class=\"line\"><span style=\"color:#F97583\">  private</span><span style=\"color:#B392F0\"> updateAnalytics</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#FFAB70\">value</span><span style=\"color:#F97583\">:</span><span style=\"color:#79B8FF\"> number</span><span style=\"color:#E1E4E8\">) {</span></span>\n<span class=\"line\"><span style=\"color:#a0aab5\">    // Update analytics</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">  }</span></span>\n<span class=\"line\"></span>\n<span class=\"line\"><span style=\"color:#F97583\">  private</span><span style=\"color:#B392F0\"> updateDOM</span><span style=\"color:#E1E4E8\">() {</span></span>\n<span class=\"line\"><span style=\"color:#a0aab5\">    // Update the DOM</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">  }</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">}</span></span>\n<span class=\"line\"></span></code></pre></div><h2 id=\"5.-signal-based-forms-in-progress\" data-line=\"157\" class=\"code-line\"><a class=\"header-anchor-link\" href=\"#5.-signal-based-forms-in-progress\" aria-hidden=\"true\"></a> 5. Signal-based forms in progress</h2>\n<p data-line=\"159\" class=\"code-line\">Angular continues expanding signal support, including a signal-based evolution of the forms system.</p>\n<h3 id=\"expected-capabilities\" data-line=\"161\" class=\"code-line\"><a class=\"header-anchor-link\" href=\"#expected-capabilities\" aria-hidden=\"true\"></a> Expected capabilities</h3>\n<ul data-line=\"163\" class=\"code-line\">\n<li data-line=\"163\" class=\"code-line\">\n<p data-line=\"163\" class=\"code-line\">Signal-based reactivity</p>\n</li>\n<li data-line=\"164\" class=\"code-line\">\n<p data-line=\"164\" class=\"code-line\">More concise form definitions</p>\n</li>\n<li data-line=\"165\" class=\"code-line\">\n<p data-line=\"165\" class=\"code-line\">Better performance</p>\n</li>\n<li data-line=\"167\" class=\"code-line\">\n<p data-line=\"167\" class=\"code-line\">Stronger type safety</p>\n</li>\n</ul>\n<h2 id=\"6.-host-binding-type-checking\" data-line=\"169\" class=\"code-line\"><a class=\"header-anchor-link\" href=\"#6.-host-binding-type-checking\" aria-hidden=\"true\"></a> 6. Host binding type checking</h2>\n<p data-line=\"171\" class=\"code-line\">Host bindings attach dynamic values to a component or directive's host element. Angular v20 adds type checking for host properties and for both <code>@HostBinding</code> and <code>@HostListener</code>.</p>\n<h3 id=\"type-check-example\" data-line=\"173\" class=\"code-line\"><a class=\"header-anchor-link\" href=\"#type-check-example\" aria-hidden=\"true\"></a> Type-check example</h3>\n<div class=\"code-block-container\"><pre class=\"shiki github-dark\" style=\"background-color:#151e2c;color:#e1e4e8\"><code class=\"code-line\" data-line=\"175\"><span class=\"line\"><span style=\"color:#E1E4E8\">@</span><span style=\"color:#B392F0\">Component</span><span style=\"color:#E1E4E8\">({</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">  ...</span><span style=\"color:#E1E4E8\">,</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">  host: {</span></span>\n<span class=\"line\"><span style=\"color:#9ECBFF\">    'role'</span><span style=\"color:#E1E4E8\">: </span><span style=\"color:#9ECBFF\">'slider'</span><span style=\"color:#E1E4E8\">,</span></span>\n<span class=\"line\"><span style=\"color:#9ECBFF\">    '[attr.aria-valuenow]'</span><span style=\"color:#E1E4E8\">: </span><span style=\"color:#9ECBFF\">'value'</span><span style=\"color:#E1E4E8\">,</span></span>\n<span class=\"line\"><span style=\"color:#9ECBFF\">    '[class.active]'</span><span style=\"color:#E1E4E8\">: </span><span style=\"color:#9ECBFF\">'isActive()'</span><span style=\"color:#E1E4E8\">,</span></span>\n<span class=\"line\"><span style=\"color:#9ECBFF\">    '[tabIndex]'</span><span style=\"color:#E1E4E8\">: </span><span style=\"color:#9ECBFF\">'disabled ? -1 : 0'</span><span style=\"color:#E1E4E8\">,</span></span>\n<span class=\"line\"><span style=\"color:#9ECBFF\">    '(keydown)'</span><span style=\"color:#E1E4E8\">: </span><span style=\"color:#9ECBFF\">'updateValue($event)'</span><span style=\"color:#E1E4E8\">,</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">  },</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">})</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">export</span><span style=\"color:#F97583\"> class</span><span style=\"color:#B392F0\"> CustomSlider</span><span style=\"color:#E1E4E8\"> {</span></span>\n<span class=\"line\"><span style=\"color:#FFAB70\">  value</span><span style=\"color:#F97583\">:</span><span style=\"color:#79B8FF\"> number</span><span style=\"color:#F97583\"> =</span><span style=\"color:#79B8FF\"> 0</span><span style=\"color:#E1E4E8\">;</span></span>\n<span class=\"line\"><span style=\"color:#FFAB70\">  disabled</span><span style=\"color:#F97583\">:</span><span style=\"color:#79B8FF\"> boolean</span><span style=\"color:#F97583\"> =</span><span style=\"color:#79B8FF\"> false</span><span style=\"color:#E1E4E8\">;</span></span>\n<span class=\"line\"><span style=\"color:#FFAB70\">  isActive</span><span style=\"color:#F97583\"> =</span><span style=\"color:#B392F0\"> signal</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#79B8FF\">false</span><span style=\"color:#E1E4E8\">);</span></span>\n<span class=\"line\"><span style=\"color:#B392F0\">  updateValue</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#FFAB70\">event</span><span style=\"color:#F97583\">:</span><span style=\"color:#B392F0\"> KeyboardEvent</span><span style=\"color:#E1E4E8\">) { </span><span style=\"color:#a0aab5\">/* ... */</span><span style=\"color:#E1E4E8\"> }</span></span>\n<span class=\"line\"><span style=\"color:#a0aab5\">  /* ... */</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">}</span></span>\n<span class=\"line\"></span></code></pre></div><h2 id=\"7.-improved-dynamic-component-creation-api\" data-line=\"195\" class=\"code-line\"><a class=\"header-anchor-link\" href=\"#7.-improved-dynamic-component-creation-api\" aria-hidden=\"true\"></a> 7. Improved dynamic component creation API</h2>\n<p data-line=\"197\" class=\"code-line\">The dynamic component API is a powerful way to create components programmatically in Angular apps.</p>\n<h3 id=\"updated-usage\" data-line=\"199\" class=\"code-line\"><a class=\"header-anchor-link\" href=\"#updated-usage\" aria-hidden=\"true\"></a> Updated usage</h3>\n<div class=\"code-block-container\"><pre class=\"shiki github-dark\" style=\"background-color:#151e2c;color:#e1e4e8\"><code class=\"code-line\" data-line=\"201\"><span class=\"line\"><span style=\"color:#E1E4E8\">@</span><span style=\"color:#B392F0\">Component</span><span style=\"color:#E1E4E8\">({</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">  standalone: </span><span style=\"color:#79B8FF\">true</span><span style=\"color:#E1E4E8\">,</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">  template: </span><span style=\"color:#9ECBFF\">`Hello {{ name }}!`</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">})</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">class</span><span style=\"color:#B392F0\"> HelloComponent</span><span style=\"color:#E1E4E8\"> {</span></span>\n<span class=\"line\"><span style=\"color:#FFAB70\">  name</span><span style=\"color:#F97583\"> =</span><span style=\"color:#9ECBFF\"> 'Angular'</span><span style=\"color:#E1E4E8\">;</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">}</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">@</span><span style=\"color:#B392F0\">Component</span><span style=\"color:#E1E4E8\">({</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">  standalone: </span><span style=\"color:#79B8FF\">true</span><span style=\"color:#E1E4E8\">,</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">  template: </span><span style=\"color:#9ECBFF\">`&lt;div id=\"hello-component-host\"&gt;&lt;/div&gt;`</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">})</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">class</span><span style=\"color:#B392F0\"> RootComponent</span><span style=\"color:#E1E4E8\"> {}</span></span>\n<span class=\"line\"><span style=\"color:#a0aab5\">// Bootstrap the application</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">const</span><span style=\"color:#79B8FF\"> applicationRef</span><span style=\"color:#F97583\"> =</span><span style=\"color:#F97583\"> await</span><span style=\"color:#B392F0\"> bootstrapApplication</span><span style=\"color:#E1E4E8\">(RootComponent);</span></span>\n<span class=\"line\"><span style=\"color:#a0aab5\">// Identify the DOM node to use as the host</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">const</span><span style=\"color:#79B8FF\"> hostElement</span><span style=\"color:#F97583\"> =</span><span style=\"color:#E1E4E8\"> document.</span><span style=\"color:#B392F0\">getElementById</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#9ECBFF\">'hello-component-host'</span><span style=\"color:#E1E4E8\">);</span></span>\n<span class=\"line\"><span style=\"color:#a0aab5\">// Get the EnvironmentInjector instance from ApplicationRef</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">const</span><span style=\"color:#79B8FF\"> environmentInjector</span><span style=\"color:#F97583\"> =</span><span style=\"color:#E1E4E8\"> applicationRef.injector;</span></span>\n<span class=\"line\"><span style=\"color:#a0aab5\">// Create a ComponentRef instance</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">const</span><span style=\"color:#79B8FF\"> componentRef</span><span style=\"color:#F97583\"> =</span><span style=\"color:#B392F0\"> createComponent</span><span style=\"color:#E1E4E8\">(HelloComponent, {hostElement, environmentInjector});</span></span>\n<span class=\"line\"><span style=\"color:#a0aab5\">// As the final step, register the newly created ref with the ApplicationRef instance</span></span>\n<span class=\"line\"><span style=\"color:#a0aab5\">// and include the component view in the change-detection cycle</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">applicationRef.</span><span style=\"color:#B392F0\">attachView</span><span style=\"color:#E1E4E8\">(componentRef.hostView);</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">componentRef.changeDetectorRef.</span><span style=\"color:#B392F0\">detectChanges</span><span style=\"color:#E1E4E8\">();</span></span>\n<span class=\"line\"></span></code></pre></div><h2 id=\"8.-other-quality-of-life-improvements\" data-line=\"228\" class=\"code-line\"><a class=\"header-anchor-link\" href=\"#8.-other-quality-of-life-improvements\" aria-hidden=\"true\"></a> 8. Other quality-of-life improvements</h2>\n<h3 id=\"typescript-5.8-support\" data-line=\"230\" class=\"code-line\"><a class=\"header-anchor-link\" href=\"#typescript-5.8-support\" aria-hidden=\"true\"></a> TypeScript 5.8 support</h3>\n<p data-line=\"231\" class=\"code-line\">TypeScript 5.8 is supported for better inference and developer experience.</p>\n<h3 id=\"untagged-template-literal-expressions-in-templates\" data-line=\"233\" class=\"code-line\"><a class=\"header-anchor-link\" href=\"#untagged-template-literal-expressions-in-templates\" aria-hidden=\"true\"></a> Untagged template literal expressions in templates</h3>\n<p data-line=\"234\" class=\"code-line\">Templates now support untagged template literal expressions.</p>\n<div class=\"code-block-container\"><pre class=\"shiki github-dark\" style=\"background-color:#151e2c;color:#e1e4e8\"><code class=\"code-line\" data-line=\"236\"><span class=\"line\"><span style=\"color:#E1E4E8\">&lt;</span><span style=\"color:#85E89D\">div</span><span style=\"color:#E1E4E8\">&gt;Balance for ${user.name}: ${balance | currency}&lt;/</span><span style=\"color:#85E89D\">div</span><span style=\"color:#E1E4E8\">&gt;</span></span>\n<span class=\"line\"></span></code></pre></div><h3 id=\"template-hmr-enabled-by-default\" data-line=\"240\" class=\"code-line\"><a class=\"header-anchor-link\" href=\"#template-hmr-enabled-by-default\" aria-hidden=\"true\"></a> Template HMR enabled by default</h3>\n<p data-line=\"241\" class=\"code-line\">Template HMR (Hot Module Replacement) is on by default, shortening reload time during development.</p>\n<h3 id=\"cleanup-of-unused-imports\" data-line=\"243\" class=\"code-line\"><a class=\"header-anchor-link\" href=\"#cleanup-of-unused-imports\" aria-hidden=\"true\"></a> Cleanup of unused imports</h3>\n<p data-line=\"244\" class=\"code-line\">A new schematic removes unused imports from the application.</p>\n<div class=\"code-block-container\"><pre class=\"shiki github-dark\" style=\"background-color:#151e2c;color:#e1e4e8\"><code class=\"code-line\" data-line=\"246\"><span class=\"line\"><span style=\"color:#B392F0\">ng</span><span style=\"color:#9ECBFF\"> generate</span><span style=\"color:#9ECBFF\"> @angular/core:cleanup-unused-imports</span></span>\n<span class=\"line\"></span></code></pre></div><h2 id=\"summary\" data-line=\"250\" class=\"code-line\"><a class=\"header-anchor-link\" href=\"#summary\" aria-hidden=\"true\"></a> Summary</h2>\n<p data-line=\"252\" class=\"code-line\">Angular v20 is a strong release for signal-based development. Resource and HTTP Resource APIs, signal-based forms in progress, and more make Angular development increasingly enjoyable.</p>\n<p data-line=\"254\" class=\"code-line\">Standout themes:</p>\n<ol data-line=\"256\" class=\"code-line\">\n<li data-line=\"256\" class=\"code-line\">\n<p data-line=\"256\" class=\"code-line\">Simpler async</p>\n<ul data-line=\"257\" class=\"code-line\">\n<li data-line=\"257\" class=\"code-line\">Unified async handling with the Resource API</li>\n<li data-line=\"258\" class=\"code-line\">Easier data fetching with HTTP Resource</li>\n<li data-line=\"259\" class=\"code-line\">Streaming for real-time data</li>\n</ul>\n</li>\n<li data-line=\"261\" class=\"code-line\">\n<p data-line=\"261\" class=\"code-line\">Better developer experience</p>\n<ul data-line=\"262\" class=\"code-line\">\n<li data-line=\"262\" class=\"code-line\">Host binding type checks</li>\n<li data-line=\"263\" class=\"code-line\">Improved dynamic component creation</li>\n<li data-line=\"264\" class=\"code-line\">Template HMR on by default</li>\n</ul>\n</li>\n<li data-line=\"266\" class=\"code-line\">\n<p data-line=\"266\" class=\"code-line\">Performance optimization</p>\n<ul data-line=\"267\" class=\"code-line\">\n<li data-line=\"267\" class=\"code-line\">Signal-based reactivity</li>\n<li data-line=\"268\" class=\"code-line\">More efficient change detection</li>\n<li data-line=\"269\" class=\"code-line\">Smaller bundle sizes</li>\n</ul>\n</li>\n</ol>\n<p data-line=\"271\" class=\"code-line\">I want to use these features to build apps users truly love. I am excited to see what comes next!</p>\n","headings":[{"id":"1.-resource-api%3A-simpler-async","text":"1. Resource API: simpler async","level":2},{"id":"basic-usage","text":"Basic usage","level":3},{"id":"resource-state","text":"Resource state","level":3},{"id":"2.-http-resource%3A-even-easier-data-fetching","text":"2. HTTP Resource: even easier data fetching","level":2},{"id":"basic-usage-1","text":"Basic usage","level":3},{"id":"3.-streaming-from-resources","text":"3. Streaming from resources","level":2},{"id":"streaming-example","text":"Streaming example","level":3},{"id":"4.-signal-api-family-stabilized","text":"4. Signal API family stabilized","level":2},{"id":"practical-example","text":"Practical example","level":3},{"id":"5.-signal-based-forms-in-progress","text":"5. Signal-based forms in progress","level":2},{"id":"expected-capabilities","text":"Expected capabilities","level":3},{"id":"6.-host-binding-type-checking","text":"6. Host binding type checking","level":2},{"id":"type-check-example","text":"Type-check example","level":3},{"id":"7.-improved-dynamic-component-creation-api","text":"7. Improved dynamic component creation API","level":2},{"id":"updated-usage","text":"Updated usage","level":3},{"id":"8.-other-quality-of-life-improvements","text":"8. Other quality-of-life improvements","level":2},{"id":"typescript-5.8-support","text":"TypeScript 5.8 support","level":3},{"id":"untagged-template-literal-expressions-in-templates","text":"Untagged template literal expressions in templates","level":3},{"id":"template-hmr-enabled-by-default","text":"Template HMR enabled by default","level":3},{"id":"cleanup-of-unused-imports","text":"Cleanup of unused imports","level":3},{"id":"summary","text":"Summary","level":2}]} as const;
